923	// TestKVTermConflictReplacesUncommittedSuffix 回归保障：新条目在 idx2 处与旧
924	// 日志任期冲突（旧任期 2、新任期 3）后，idx2 及其后的未提交旧后缀被整段替换；
925	// 替换区间内的新条目（idx3 任期 4）即使与旧位置同任期、命令不同，也不再逐位
926	// 比对，复制照常成功。已提交前缀 idx1 完整保留，原 idx4 被删除，最终日志只剩
927	// 三条。开启 applyKV 时提交与应用位置都推进到 3：键值表只反映新日志的命令
928	// （balance=300、receipt=ok），旧后缀中的 delete balance 与 set legacy=old
929	// 不得留下任何效果，也没有应用错误。
930	func TestKVTermConflictReplacesUncommittedSuffix(t *testing.T) {
931		out := runKV(t, uncommittedSuffixInitial(),
932			AppendRequest{Term: 4, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
933				Entries: []LogEntry{
934					entry(2, 3, "set balance=300"),
935					entry(3, 4, "set receipt=ok"), // 与旧 idx3 同任期不同命令：位于被替换后缀内，允许
936				}},
937		)
938	
939		if len(out.Results) != 1 {
940			t.Fatalf("got %d results, want 1", len(out.Results))
941		}
942		result := out.Results[0]
943		if !result.Accepted || result.Reason != ReasonOK {
944			t.Fatalf("suffix replacement should be accepted: %+v", result)
945		}
946		if result.Term != 4 || result.CommittedIndex != 3 {
947			t.Fatalf("result state = term %d ci %d, want term 4 ci 3", result.Term, result.CommittedIndex)
948		}
949		if got := appliedIndexOf(t, result); got != 3 {
950			t.Fatalf("result appliedIndex = %d, want 3", got)
951		}
952		if result.ApplyError != nil {
953			t.Fatalf("unexpected apply error: %+v", result.ApplyError)
954		}
955	
956		// 最终日志：已提交前缀保留，idx2/idx3 换成新条目，原 idx4 被删除。
957		wantLog := []LogEntry{
958			entry(1, 1, "set balance=100"),
959			entry(2, 3, "set balance=300"),
960			entry(3, 4, "set receipt=ok"),
961		}
962		if !reflect.DeepEqual(out.FinalLog, wantLog) {
963			t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
964		}
965		if out.FinalTerm != 4 || out.FinalCommittedIndex != 3 {
966			t.Fatalf("final state = term %d ci %d, want term 4 ci 3", out.FinalTerm, out.FinalCommittedIndex)
967		}
968		if *out.FinalAppliedIndex != 3 {
969			t.Fatalf("final appliedIndex = %d, want 3", *out.FinalAppliedIndex)
970		}
