1379			`{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"APPLIEDINDEX":"0"}],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
1380			`{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"ApplyError":{"index":"2","reason":"x"}}],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
1381		}
1382		for _, data := range badInputs {
1383			var out ReplicateOutput
1384			if err := json.Unmarshal([]byte(data), &out); err == nil {
1385				t.Fatalf("expected decode error for %s", data)
1386			}
1387		}
1388	}
1389	
1390	// TestKVRoundTripCaseFoldedFailedReuseKeepsPreviousResult 复用已有结果对象读入
1391	// 大小写变体字段名的非法 JSON 时必须报错，并完整保留读入前的结果（含其应用
1392	// 状态）；之后输出不能混入这次读入的任何内容，也不能被变体名打开开关。
1393	func TestKVRoundTripCaseFoldedFailedReuseKeepsPreviousResult(t *testing.T) {
1394		original := runKV(t, InitialState{CurrentTerm: 1, CommittedIndex: 1, Log: []LogEntry{
1395			entry(1, 1, "set x=1"),
1396		}},
1397			AppendRequest{Term: 1, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
1398				Entries: []LogEntry{entry(2, 1, "set bad"), entry(3, 1, "set k=v")}},
1399		)
1400		originalJSON, err := json.Marshal(original)
1401		if err != nil {
1402			t.Fatal(err)
1403		}
1404		badInputs := []string{
1405			// 错误位于某条请求答复内，字段名大写。
1406			`{"results":[{"accepted":true,"reason":"ok","term":9,"committedIndex":9,"APPLIEDINDEX":"3"}],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[]}`,
1407			// 最终层：应用索引写成字符串，字段名首字母大写。
1408			`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"FinalAppliedIndex":"9"}`,
1409			// 最终层：键值表写成数组，字段名全大写。
1410			`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"FINALKV":["nope"]}`,
1411		}
1412		for _, bad := range badInputs {
1413			var out ReplicateOutput
1414			if err := json.Unmarshal(originalJSON, &out); err != nil {
1415				t.Fatal(err)
1416			}
1417			if err := json.Unmarshal([]byte(bad), &out); err == nil {
1418				t.Fatalf("expected decode error for %s", bad)
1419			}
1420			reencoded, err := json.Marshal(out)
1421			if err != nil {
1422				t.Fatal(err)
1423			}
1424			if string(reencoded) != string(originalJSON) {
1425				t.Fatalf("previous result not preserved after failed decode of %s:\nwant %s\n got %s",
1426					bad, originalJSON, reencoded)
1427			}
1428		}
1429	}
1430	
1431	// TestKVRoundTripCaseFoldedSuccessfulReuseNoResidue 复用结果对象成功读入下一份
1432	// JSON 时只保留本次内容：先读入以变体名记录应用状态的结果，再读入完全没有
1433	// 应用字段的旧结果，后一次输出不得残留前一次的键值表、错误或应用位置；反方向
1434	// （先旧后变体）则必须按本次内容补齐完整应用字段。
1435	func TestKVRoundTripCaseFoldedSuccessfulReuseNoResidue(t *testing.T) {
1436		variantApplied := `{"results":[{"accepted":true,"reason":"ok","term":1,` +
1437			`"committedIndex":1,"AppliedIndex":1,"ApplyError":null}],` +
1438			`"finalTerm":1,"finalCommittedIndex":1,` +
1439			`"finalLog":[{"index":1,"term":1,"command":"set x=1"}],` +
1440			`"FinalAppliedIndex":1,"FinalKV":{"x":"1"},"FINALAPPLYERROR":null}`
1441		plain := `{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":1}],` +
1442			`"finalTerm":1,"finalCommittedIndex":1,` +
1443			`"finalLog":[{"index":1,"term":1,"command":"set x=1"}]}`
1444	
1445		// 先变体后旧结果：无残留。
1446		var out ReplicateOutput
1447		if err := json.Unmarshal([]byte(variantApplied), &out); err != nil {
1448			t.Fatal(err)
1449		}
1450		if err := json.Unmarshal([]byte(plain), &out); err != nil {
1451			t.Fatal(err)
1452		}
1453		body, err := json.Marshal(out)
1454		if err != nil {
1455			t.Fatal(err)
1456		}
1457		for _, field := range []string{"appliedIndex", "applyError", "finalAppliedIndex", "finalKV", "finalApplyError"} {
1458			if strings.Contains(string(body), field) {
1459				t.Fatalf("stale apply field %q after reusing object: %s", field, body)
1460			}
1461		}
1462		if out.FinalKV != nil || out.FinalAppliedIndex != nil || out.FinalApplyError != nil {
1463			t.Fatalf("stale apply state in %+v", out)
1464		}
1465	
1466		// 先旧结果后变体：按本次内容带齐标准字段。
1467		var out2 ReplicateOutput
1468		if err := json.Unmarshal([]byte(plain), &out2); err != nil {
1469			t.Fatal(err)
1470		}
1471		if err := json.Unmarshal([]byte(variantApplied), &out2); err != nil {
1472			t.Fatal(err)
1473		}
1474		body2, err := json.Marshal(out2)
1475		if err != nil {
1476			t.Fatal(err)
1477		}
1478		m := decodeMap(t, body2)
1479		mustHaveKeys(t, m, "final output",
1480			"finalAppliedIndex", "finalKV", "finalApplyError")
1481		if m["finalAppliedIndex"] != float64(1) ||
1482			!reflect.DeepEqual(m["finalKV"], map[string]any{"x": "1"}) ||
1483			m["finalApplyError"] != nil {
1484			t.Fatalf("variant-keyed apply state not restored after reuse: %v", m)
1485		}
1486		results := resultMaps(t, m)
1487		mustHaveKeys(t, results[0], "applied request", "appliedIndex", "applyError")
1488	}
